@props([
    'name',
    'variant' => 'outline',
])

@php
    use App\Support\Stencil\Icon\IconPathResolver;
    use App\Support\Stencil\ProjectConfig;

    $resolvedName = IconPathResolver::normalizeName((string) $name);
    $iconPath = app(ProjectConfig::class)->resolvedIconsPath().'/'.$resolvedName.'.blade.php';

    if (! is_file($iconPath)) {
        throw new \RuntimeException("Icon [{$resolvedName}] is not installed. Run: php artisan stencil:icon {$resolvedName}");
    }

    $componentName = 'ui::icons.'.$resolvedName;
@endphp

<x-dynamic-component :component="$componentName" :variant="$variant" {{ $attributes }} />

@props([
    'variant' => 'outline',
])

@php
    $loadingVariant = \App\Support\Stencil\Icon\IconVariant::normalize($variant ?? 'outline');
    $loadingIconClasses = \App\Support\Stencil\Icon\IconVariant::classString($loadingVariant);
    $loadingStrokeWidth = \App\Support\Stencil\Icon\IconVariant::strokeWidth($loadingVariant);
    $loadingPixelSize = \App\Support\Stencil\Icon\IconVariant::pixelSize($loadingVariant);
    $loadingMergedClass = trim($loadingIconClasses.' animate-spin '.($class ?? ''));
@endphp

<svg
    class="{{ $loadingMergedClass }}"
    width="{{ $loadingPixelSize }}"
    height="{{ $loadingPixelSize }}"
    data-icon
    data-button-loading-icon
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="{{ $loadingStrokeWidth }}"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
>
    <path d="M21 12a9 9 0 1 1-6.219-8.56" />
</svg>

@props([
    'variant' => 'outline',
])

@php
    use App\Support\Stencil\Icon\IconVariant;

    $normalizedVariant = IconVariant::normalize($variant);
    $iconClasses = IconVariant::classString($normalizedVariant);
    $strokeWidth = IconVariant::strokeWidth($normalizedVariant);
    $pixelSize = IconVariant::pixelSize($normalizedVariant);
@endphp

<svg
    {{ $attributes->class($iconClasses) }}
    width="{{ $pixelSize }}"
    height="{{ $pixelSize }}"
    data-icon
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    fill="none"
    stroke="currentColor"
    stroke-width="{{ $strokeWidth }}"
    stroke-linecap="round"
    stroke-linejoin="round"
    aria-hidden="true"
>
    {{ $slot }}
</svg>
